export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = c => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/
const D = '\\d+(?:_\\d+)*'
const INT = new RegExp(`^[+-]?${D}$`)
const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)

class LineParser {
  constructor(text, root) {
    this.s = text
    this.i = 0
    this.root = root
    this.cur = root
    this.curPath = []
  }

  fail(msg) { throw new Error(msg) }
  ws() { while (this.i < this.s.length && isWs(this.s[this.i])) this.i++ }
  peek() { return this.s[this.i] }
  atEnd() { // end of line or comment
    const c = this.peek()
    return c === undefined || c === '#' || c === ';'
  }

  string(q) {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= s.length) this.fail('unterminated string')
      const c = s[this.i]
      if (c === q) { this.i++; return out }
      if (q === '"' && c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) this.fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; this.i += 2 } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else this.fail(`invalid escape \\${String.fromCodePoint(s.codePointAt(this.i + 1))}`)
      } else { out += c; this.i++ }
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }

  // Walk from table `t` along names, creating tables; returns the table.
  walk(t, names, path) {
    for (const n of names) {
      path = [...path, n]
      let c = t.map.get(n)
      if (!c) { c = newTable(); t.map.set(n, c) }
      if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
      else if (c.t !== 'table') this.fail(`${path.join('.')} is not a table`)
      t = c
    }
    return t
  }

  assign(base, basePath, keys, value) {
    const t = this.walk(base, keys.slice(0, -1), basePath)
    const last = keys[keys.length - 1]
    if (t.map.has(last)) this.fail(`key ${[...basePath, ...keys].join('.')} is defined twice`)
    t.map.set(last, value)
  }

  value(path) {
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string(c) }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    this.fail(`invalid value ${w}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      const c = this.peek()
      if (c === undefined || c === '#' || c === ';') this.fail('unterminated array')
      if (c === ']' && (items.length === 0 || this.afterComma)) { this.i++; break }
      this.afterComma = false
      items.push(this.value(path))
      this.ws()
      const d = this.peek()
      if (d === ',') { this.i++; this.afterComma = true } else if (d === ']') { this.i++; break } else this.fail('unterminated array')
    }
    this.afterComma = false
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const t = newTable()
    this.ws()
    if (this.peek() === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.peek() === undefined || this.peek() === '#' || this.peek() === ';') this.fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value([...path, ...keys])
      this.assign(t, path, keys, v)
      this.ws()
      const d = this.peek()
      if (d === ',') this.i++
      else if (d === '}') { this.i++; return t } else this.fail('unterminated inline table')
    }
  }

  trailing(msg) {
    this.ws()
    if (!this.atEnd()) this.fail(msg)
  }

  header() {
    this.i++
    const aot = this.peek() === '['
    if (aot) this.i++
    this.ws()
    const names = this.dotted()
    this.ws()
    const close = (aot ? ']]' : ']')
    if (this.s.startsWith(close, this.i)) this.i += close.length
    else this.fail('unterminated table header')
    this.trailing('trailing text after a table header')
    const parent = this.walk(this.root, names.slice(0, -1), [])
    const last = names[names.length - 1]
    const path = names.join('.')
    const ex = parent.map.get(last)
    if (aot) {
      let arr = ex
      if (!arr) { arr = { t: 'array', items: [], aot: true }; parent.map.set(last, arr) }
      else if (arr.t !== 'array' || !arr.aot) this.fail(`${path} is not an array of tables`)
      const t = newTable()
      t.header = true
      arr.items.push(t)
      this.cur = t
    } else {
      let t = ex
      if (!t) { t = newTable(); parent.map.set(last, t) }
      else if (t.t !== 'table') this.fail(`${path} is not a table`)
      else if (t.header) this.fail(`table ${path} is defined twice`)
      t.header = true
      this.cur = t
    }
    this.curPath = names
  }

  line() {
    this.ws()
    if (this.peek() === '[') return this.header()
    const keys = this.dotted()
    this.ws()
    if (this.peek() !== '=') this.fail('expected key = value')
    this.i++
    this.ws()
    const v = this.value([...this.curPath, ...keys])
    this.trailing('trailing text after a value')
    this.assign(this.cur, this.curPath, keys, v)
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let p = new LineParser('', root)
  lines.forEach((text, idx) => {
    const m = /^[ \t]*(.?)/.exec(text)
    if (m[1] === '' || m[1] === '#' || m[1] === ';') return
    p.s = text
    p.i = 0
    try {
      p.line()
    } catch (e) {
      if (e instanceof ParseError) throw e
      if (e.constructor !== Error) throw e
      throw new ParseError(e.message, idx + 1)
    }
  })
  return root
}
